def select(t,kind):
 if kind=='pokemon-hindi':return t['id'].startswith('pokemon-')and t['category']=='anime-series'and any(s['audio_language']=='Hindi'for s in t['seasons'])
 if kind=='hindi-films':return t['category']=='anime-movies'and any(s['audio_language']=='Hindi'for s in t['seasons'])
 if kind=='hindi-anime':return t['category']=='anime-series'and any(s['audio_language']=='Hindi'for s in t['seasons'])
 if kind=='sub-anime':return t['category']=='anime-series'and any('English'in s.get('subtitle_languages',[])for s in t['seasons'])
 if kind=='sub-films':return t['category']=='anime-movies'and any('English'in s.get('subtitle_languages',[])for s in t['seasons'])
 if kind=='south-hindi':return t['provider']=='Goldmines'
 if kind=='sub-drama':return t['category']=='k-dramas'and any('English'in s.get('subtitle_languages',[])for s in t['seasons'])
 if kind=='seasons':return t['category']=='anime-series'and len(t['seasons'])>1
 if kind=='anime-india':return t['category']=='anime-series'
 if kind=='hindi-movies':return t['category']=='movies'and any(s['audio_language']=='Hindi'for s in t['seasons'])
 if kind=='dub-films':return t['category']=='anime-movies'and any(s['audio_language']=='English'for s in t['seasons'])
 if kind=='dub-anime':return t['category']=='anime-series'and any(s['audio_language']=='English'for s in t['seasons'])
 if kind=='kdrama-all':return t['category']=='k-dramas'
 if kind=='anime-movies-all':return t['category']=='anime-movies'
 if kind=='jojo':return t['id']=='jojos-bizarre-adventure'
 if kind=='ac':return t['id']=='assassination-classroom'
 if kind=='recent-hindi':return any(s['audio_language']=='Hindi' and s.get('last_checked','')>=_RECENT_CUTOFF for s in t['seasons'])
 if kind=='cote':return t['id']=='classroom-of-the-elite'
 if kind=='mob':return t['id']=='mob-psycho-100'
 if kind=='hxh':return t['id']=='hunter-x-hunter'
 if kind=='aot':return t['id']=='attack-on-titan'
 if kind=='spy-movie':return t['id']=='spy-x-family-code-white'
 if kind=='who-are-you':return t['id']=='who-are-you-school-2015'
 return False

def build_landings(page,cards,titles,esc,base):
 for item in PAGES:
  path='/discover/'+item['slug']+'/'
  ts=[t for t in titles if select(t,item['kind'])]
  if item['kind']=='hindi-films':ts.sort(key=lambda t:t.get('browse_priority',100))
  if item['kind']=='recent-hindi' and not ts:
   _h=[t for t in titles if any(s['audio_language']=='Hindi' for s in t['seasons'])]
   _h.sort(key=lambda t:max(s.get('last_checked','') for s in t['seasons']),reverse=True)
   ts=_h[:10]
  if item['kind']=='recent-hindi':ts.sort(key=lambda t:max(s.get('last_checked','') for s in t['seasons'] if s['audio_language']=='Hindi'),reverse=True)
  if not ts:continue
  body='<article class="prose"><p class="eyebrow">ANILOVE INDIA · WATCHING GUIDE</p><h1>'+esc(item['title'])+'</h1><p class="lead">'+esc(item['intro'])+'</p>'
  if item.get('edition_table'):
   body+='<blockquote>'+esc(item['intro'])+'</blockquote><p><a class="btn primary" href="#collection-titles">Choose a title</a></p>'
  for heading,text in item['paragraphs']:body+='<h2>'+esc(heading)+'</h2><p>'+esc(text)+'</p>'
  if item.get('edition_table'):
   count=sum(len(s['episodes'])for t in ts for s in t['seasons']if s['audio_language']=='Hindi')
   body+='<h2>Current Hindi edition selection</h2><p>'+str(len(ts))+' titles and '+str(count)+' checked Hindi uploads. Counts describe this catalogue, not the full publisher library.</p><table><thead><tr><th>Title</th><th>Edition</th><th>Listed uploads</th></tr></thead><tbody>'
   for t in ts:
    for edition in t['seasons']:
     if edition['audio_language']=='Hindi':body+='<tr><td><a href="/title/'+esc(t['id'])+'/#'+esc(edition['id'])+'">'+esc(t['title'])+'</a></td><td>'+esc(edition['label'])+'</td><td>'+str(len(edition['episodes']))+'</td></tr>'
   body+='</tbody></table><h2>Check an edition before watching</h2><p>Title pages preserve the uploader link and language labels. Separate episode uploads offer direct episode selection; one long compilation offers a single timeline. The original YouTube page can provide publisher updates that have not reached this catalogue yet.</p><p>Maintained by Nitesh Patel. Read <a href="/about/">About AniLove</a> and <a href="/contact/">report a source issue</a>. No invented ratings, viewing statistics or complete-season claims are used.</p>'
  body+='</article><section class="section" id="collection-titles"><div class="section-heading"><h2>Choose a title</h2></div>'+cards(ts)+'</section><article class="prose"><h2>Questions about this collection</h2>'
  for q,a in item['faqs']:body+='<details open><summary>'+esc(q)+'</summary><p>'+esc(a)+'</p></details>'
  body+='<p><a href="/discover/pokemon-hindi-episodes/">Pokémon Hindi episodes</a> · <a href="/discover/hindi-anime-movies/">Hindi animated movies</a> · <a href="/search/">Search all titles</a> · <a href="/seasons/">Browse seasons</a> · <a href="/contact/">Request on WhatsApp</a></p></article>'
  schema={'@context':'https://schema.org','@graph':[{'@type':'CollectionPage','@id':base+path,'name':item['title'],'description':item['intro'],'url':base+path,'inLanguage':'en-IN','mainEntity':{'@type':'ItemList','numberOfItems':len(ts),'itemListElement':[{'@type':'ListItem','position':i+1,'url':base+'/title/'+t['id']+'/','name':t['title']}for i,t in enumerate(ts)]}},{'@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}}for q,a in item['faqs']]},{'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'AniLove India','item':base+'/'},{'@type':'ListItem','position':2,'name':item['title'],'item':base+path}]}]}
  page(path,item['title'],body,item['intro'],schema)
